def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    flag_values = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day_text, flag = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc
        if flag not in flag_values:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")
        out.append({"id": id_, "day": day, "flagged": flag_values[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    by_id = {e["id"]: e for e in events}
    return sorted(by_id.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        day = e["day"]
        if start_day <= day <= end_day and e["flagged"] is True:
            counts[day - start_day] += 1
    return counts
