)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert isinstance(rate, float)
    assert rate == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (1, 4), (2, 6), (5, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_parse_transcript_log_trims_fields_and_skips_nonrecords():
    lines = ["", "  \t\n", "# comment", " \t# comment,with,commas", " x , 3 , 1 ", "y,4,0", "z,5,  "]
    events = parse_transcript_log(lines)
    assert [(event["id"], event["day"]) for event in events] == [("x", 3), ("y", 4), ("z", 5)]
    assert events[0]["flagged"] is True
    assert events[1]["flagged"] is False
    assert events[2]["flagged"] is None


@pytest.mark.parametrize("line", ["y,4", "y,4,1,extra", "y,not-an-int,0"])
def test_parse_transcript_log_errors_count_skipped_lines(line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["  ", " # comment", "x,3,1", line])


def test_dedupe_transcripts_keeps_last_id_and_sorts_by_day_then_id():
    events = parse_transcript_log(["a,9,1", "b,2,1", "c,1,1", "a,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_daily_flag_counts_includes_gaps_and_ignores_outside_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "a": parse_transcript_log(["a,1,1"]),
        "b": parse_transcript_log(["b,4,1", "c,5,0"]),
        "empty": [],
    }
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_and_excludes_empty_groups():
    groups = {
        "empty": [],
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "b": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]


